oxy_webhelp_navlinks = {"agents_toc-d4384e3491":{"topics":[{"title":"Working with agents","shortdesc":"<p class=\"shortdesc\">You can program HCL Notes® to perform tasks automatically using agents (also known as macros). Agents can help you perform repetitive tasks, such as managing documents and sending memos. <\/p>","href":"agt_automate_task_using_agent_c.html","attributes":{"data-id":"agt_automate_task_using_agent_c"},"menu":{"hasChildren":true},"tocID":"agt_automate_task_using_agent_c-d4384e3502","next":"agt_automate_task_using_agent_c-d4384e3502"},{"title":"Sample agents","shortdesc":"<p class=\"shortdesc\">These topics contain sample agents that you can use to better understand how to create your own agents.<\/p>","href":"agt_samples.html","attributes":{"data-id":"agt_samples"},"menu":{"hasChildren":true},"tocID":"agt_samples-d4384e3560","next":"agt_samples-d4384e3560"},{"title":"Advanced agents topics","shortdesc":"<p class=\"shortdesc\">These topics contain additional information about agent conditions and triggers, for more advanced users.<\/p>","href":"agt_adv.html","attributes":{"data-id":"agt_adv"},"menu":{"hasChildren":true},"tocID":"agt_adv-d4384e3626","next":"agt_adv-d4384e3626"}]}};